                    graphics.drawRGB(this.b[0].a, 0, this.b[0].b, this.posX + this.b[0].d - this.t[4 + (this.t[0] << 1)], this.posY + this.b[0].e + this.t[4 + (this.t[0] << 1) + 1], this.b[0].b, this.b[0].c, true);
